// Generated by gstack /ship Step 7 (test coverage audit), pass 1.
//
// Value: protects=loadJobs classifies Harbor trials: no reward is infra with its exception, reward>=1 passes,
//   timeouts and budget stops stay graded, cost and skill opens come from the agent files;
//   fails_when=an ungraded trial counts as fail, or cost/arm/model/skill opens are read from the wrong place;
//   why_new=analysis.test.ts builds Trial objects by hand and never reads a job directory; seam=none;
//   no_claim=Harbor's real result.json schema (hand-written fixtures modeled on the reader)
import { afterAll, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { loadJobs } from "../analysis/analyze.ts";

const root = mkdtempSync(join(tmpdir(), "laneb-jobs-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));

const trial = (name: string, files: Record<string, unknown>) => {
  for (const [rel, value] of Object.entries(files)) {
    const p = join(root, "job", name, rel);
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, typeof value === "string" ? value : JSON.stringify(value));
  }
};
const config = (task: string, arm: string) => ({ task: { path: `/run/tasks/${task}` }, agent: { model_name: "anthropic/claude-haiku-5-5", kwargs: { arm, upstream_model: "claude-haiku-5-5" } } });

test("loadJobs classifies graded, timed-out, budget-stopped and infra trials from a job directory", () => {
  trial("a-pass", {
    "result.json": { trial_name: "a-pass", verifier_result: { rewards: { reward: 1 } } },
    "config.json": config("t1", "gstack"),
    "agent/laneb-summary.json": { session: { spent_micros: 2_500_000, requests: 4, refused: 1, refused_budget: 1 }, wall_s: 12 },
    "agent/sdk-messages.jsonl": JSON.stringify({ type: "AssistantMessage", content: [{ name: "Skill", input: { skill: "/investigate" } }] }) + "\n",
  });
  trial("b-infra", {
    "result.json": { trial_name: "b-infra", exception_info: { exception_type: "DockerError", exception_message: "build failed" } },
    "config.json": config("t2", "none"),
  });
  trial("c-timeout", {
    "result.json": { trial_name: "c-timeout", verifier_result: { rewards: { reward: 0 } }, exception_info: { exception_type: "AgentTimeoutError", exception_message: "slow" } },
    "config.json": config("t3", "placebo"),
  });
  trial("d-first-reward", {
    "result.json": { trial_name: "d-first-reward", verifier_result: { rewards: { score: 1 } } },
    "config.json": config("t4", "none"),
  });
  trial("e-no-config", { "result.json": { trial_name: "e-no-config", verifier_result: { rewards: { reward: 1 } } } });
  writeFileSync(join(root, "job", "job.log"), "not a trial");

  const trials = loadJobs([join(root, "job")]).sort((x, y) => x.trialName.localeCompare(y.trialName));
  expect(trials.map((t) => t.trialName)).toEqual(["a-pass", "b-infra", "c-timeout", "d-first-reward"]);
  const [a, b, c, d] = trials;
  expect(a).toMatchObject({ task: "t1", arm: "gstack", model: "claude-haiku-5-5", outcome: "pass", reason: "session budget stop, patch graded", costUsd: 2.5, requests: 4, refused: 1, budgetStop: true, agentTimeout: false, wallS: 12, skillOpens: ["investigate"] });
  expect(b).toMatchObject({ task: "t2", outcome: "infra", reason: "DockerError: build failed", costUsd: 0, skillOpens: [], wallS: null });
  expect(c).toMatchObject({ task: "t3", arm: "placebo", outcome: "fail", reason: "agent timeout, patch graded", agentTimeout: true, budgetStop: false });
  expect(d).toMatchObject({ task: "t4", outcome: "pass", reason: "graded" });
});
